namespace KiteWindPoll {
constexpr uint32_t POLL_INTERVAL_MS = 600000;
constexpr uint32_t HOLD_MS = 1800000;
constexpr unsigned FAILURE_CAP = 1000;

inline uint32_t retryDelayMs(unsigned failures, bool unauthorized) {
  constexpr uint32_t retries[] = {30000, 60000, 120000, 300000};
  return unauthorized || failures == 0 ? POLL_INTERVAL_MS : retries[failures < 4 ? failures - 1 : 3];
}

inline bool holdsState(uint32_t lastSuccess, uint32_t now) {
  return static_cast<uint32_t>(now - lastSuccess) < HOLD_MS;
}
// AI: end

// Note: holdsState(0, now) is true in the first 30 min after boot, so callers
// must keep a "has state" flag and clear it when the hold expires.
// AI: below section was generated by an AI
// Saturating consecutive-failure counter.
inline unsigned nextFailures(unsigned failures) {
  return failures >= FAILURE_CAP ? FAILURE_CAP : failures + 1;
}

enum class HostClass : uint8_t { Invalid, LanIpv4, PublicIpv4, Localhost, LocalName, PublicName };
enum class Scheme : uint8_t { Refused, Http, Https };

// Only the four listed LAN ranges: 10/8, 172.16/12, 192.168/16, 127/8.
inline bool isLanAddress(uint8_t a, uint8_t b) {
  return a == 10 || a == 127 || (a == 172 && b >= 16 && b <= 31) || (a == 192 && b == 168);
}

namespace detail {
inline char lower(char c) { return c >= 'A' && c <= 'Z' ? static_cast<char>(c + 32) : c; }
inline bool digit(char c) { return c >= '0' && c <= '9'; }
inline bool alnum(char c) { return digit(c) || (lower(c) >= 'a' && lower(c) <= 'z'); }
inline size_t length(const char* s, size_t max) {
  size_t n = 0;
  while (n < max && s[n]) n++;
  return n;
}
// Case-insensitive compare of s[0..n) with a lowercase literal.
inline bool equalsLower(const char* s, size_t n, const char* literal) {
  size_t i = 0;
  for (; i < n; i++) if (!literal[i] || lower(s[i]) != literal[i]) return false;
  return !literal[i];
}
// Canonical dotted quad: four 0-255 octets, no leading zeros.
inline bool parseIpv4(const char* s, size_t n, uint8_t out[4]) {
  size_t i = 0;
  for (int part = 0; part < 4; part++) {
    size_t start = i;
    unsigned value = 0;
    while (i < n && digit(s[i])) {
      value = value * 10 + static_cast<unsigned>(s[i] - '0');
      if (value > 255) return false;
      i++;
    }
    size_t digits = i - start;
    if (!digits || digits > 3 || (digits > 1 && s[start] == '0')) return false;
    out[part] = static_cast<uint8_t>(value);
    if (part < 3) {
      if (i >= n || s[i] != '.') return false;
      i++;
    }
  }
  return i == n;
}
// Letters, digits and inner hyphens; labels of 1-63 chars; numeric last label is rejected.
inline bool validDnsName(const char* s, size_t n, size_t& lastLabel, size_t& lastLabelLen) {
  size_t start = 0;
  for (size_t i = 0; i <= n; i++) {
    if (i < n && s[i] != '.') {
      if (!alnum(s[i]) && s[i] != '-') return false;
      continue;
    }
    size_t len = i - start;
    if (!len || len > 63 || s[start] == '-' || s[i - 1] == '-') return false;
    lastLabel = start;
    lastLabelLen = len;
    start = i + 1;
  }
  for (size_t i = 0; i < lastLabelLen; i++) if (!digit(s[lastLabel + i])) return true;
  return false;
}
}  // namespace detail

// Syntax-only classification; never resolves names. Needs a NUL-terminated string.
inline HostClass classifyHost(const char* host) {
  if (!host) return HostClass::Invalid;
  size_t n = detail::length(host, 254);
  if (!n || n > 253) return HostClass::Invalid;
  uint8_t ip[4];
  if (detail::parseIpv4(host, n, ip))
    return isLanAddress(ip[0], ip[1]) ? HostClass::LanIpv4 : HostClass::PublicIpv4;
  size_t last = 0, lastLen = 0;
  if (!detail::validDnsName(host, n, last, lastLen)) return HostClass::Invalid;
  if (detail::equalsLower(host, n, "localhost")) return HostClass::Localhost;
  if (last > 0 && detail::equalsLower(host + last, lastLen, "local")) return HostClass::LocalName;
  return HostClass::PublicName;
}

// Port 443 selects HTTPS (S3 build only); other ports allow HTTP for LAN hosts only.
inline Scheme selectScheme(const char* host, unsigned port, bool httpsBuild) {
  HostClass kind = classifyHost(host);
  if (kind == HostClass::Invalid || port == 0 || port > 65535) return Scheme::Refused;
  if (port == 443) return httpsBuild ? Scheme::Https : Scheme::Refused;
  return kind == HostClass::PublicName || kind == HostClass::PublicIpv4 ? Scheme::Refused : Scheme::Http;
}

// Check the numeric connection address (octets in dotted order, not an
// IPAddress uint32_t) before sending the key.
inline bool connectionAllowed(Scheme scheme, HostClass kind, const uint8_t address[4]) {
  if (scheme == Scheme::Https) return kind != HostClass::Invalid;
  if (scheme != Scheme::Http) return false;
  return (kind == HostClass::LanIpv4 || kind == HostClass::Localhost || kind == HostClass::LocalName) &&
         isLanAddress(address[0], address[1]);
}
}  // namespace KiteWindPoll
